/*
 * The camera, as canvas sources: the module drops a live frame into the
 * PREVIEW canvas (~8fps, small) and SNAP copies one full frame into the
 * PHOTO canvas. The UI just blits both -- the op stream stays tiny and
 * remote viewers get the pictures in-band like any canvas. Everything
 * arrives async: the module nudges state (camf, snap) and this view
 * simply renders.
 */
var HAVE_CAM = false;
if (typeof sys !== 'undefined' && typeof sys.mods === 'function') {
  try {
    var mods = JSON.parse('' + sys.mods());
    for (var mi = 0; mi < mods.length; mi++) {
      if (mods[mi].name === 'cam') HAVE_CAM = true;
    }
  } catch (e) {}
}
if (HAVE_CAM) {
  UI.set({ camOk: sys.modCtl('cam', 'start') ? 1 : 0 });
  /* the mounted rotation is a SETTING: restore it before first frame */
  var savedRot = parseInt(configStorage.get('cam.rot', '0')) || 0;
  if (savedRot) sys.modCtl('cam', 'rot' + savedRot);
  UI.set({ camrot: savedRot });
  /* leaving the example RELEASES the sensor: no background capture,
     no per-frame nudges re-rendering the menu */
  if (typeof UI.onCleanup === 'function') {
    UI.onCleanup(function () { sys.modCtl('cam', 'stop'); });
  }
}

function App() {
  var ok = UI.state.camOk;
  var rot = UI.state.camrot || 0;
  var odd = rot % 2 === 1;
  var W = gfx.width(), H = gfx.height();
  /* the PHOTO is the background: contained in the screen at the
     mounted aspect, so any orientation just works */
  var aw = odd ? 3 : 4, ah = odd ? 4 : 3;
  var bw = Math.min(W, Math.floor(H * aw / ah));
  var bh = Math.floor(bw * ah / aw);
  if (bh > H) { bh = H; bw = Math.floor(bh * aw / ah); }
  var bx = Math.floor((W - bw) / 2), by = Math.floor((H - bh) / 2);
  /* the PREVIEW overlays as picture-in-picture, same aspect */
  var pw = Math.floor(W / 4);
  var ph = Math.floor(pw * ah / aw);

  return (
    <box h={H} bg={0x000000}>
      <abs x={bx} y={by}>
        {h('canvas', { src: 3, w: bw, h: bh })}
      </abs>
      <abs x={8} y={H - ph - 8}>
        <box border={0xffffff} borderW={1}>
          {h('canvas', { src: 2, w: pw, h: ph })}
        </box>
      </abs>
      <abs x={8} y={8}>
        <text text={!HAVE_CAM ? 'no camera module here'
                  : ok ? 'LIVE ' + (UI.state.camf || 0)
                  : 'camera failed to start'}
              size={1} color={ok ? UI.theme.ok : UI.theme.warn} />
      </abs>
      <abs x={0} y={H - 48}>
        {/* full-width row, flex spacer: right-aligned at ANY size */}
        <row w={W} padR={8} gap={8}>
          <box flex={1} />
          <Button label="SNAP" size={2} bg={UI.theme.accent}
                  onTap={function () {
                    if (HAVE_CAM) sys.modCtl('cam', 'snap');
                  }} />
          <Button label="ROT" size={2} bg={UI.theme.key}
                  onTap={function () {
                    if (!HAVE_CAM) return;
                    sys.modCtl('cam', 'rot');
                    configStorage.set('cam.rot', ((UI.state.camrot || 0) + 1) % 4);
                  }} />
        </row>
      </abs>
    </box>
  );
}

UI.mount(App);

/*
 * Freehand drawing with a CANVAS SOURCE backing - draw's little sibling,
 * restructured around sys.canvas. The live stroke renders as ordinary
 * ops (fast, smooth, previewed OVER the bitmap); on release it is
 * committed into canvas 0 and vanishes from the op stream entirely, so
 * a hundred strokes cost the same as none: one blit op per frame. The
 * remote sees the committed pixels arrive in-band as a JPEG keyed by
 * the canvas generation.
 *
 * Hosts without the natives keep strokes as paths, draw-style, so the
 * example stays developable anywhere.
 */
/* The drawing area's height, decided ONCE: the canvas source is allocated
   at exactly the size the canvas element is drawn at. When those two
   disagree the blit stretches, and a stroke committed after its preview
   lands somewhere other than where it was drawn -- which is what happened
   the moment the round layout gave the canvas the whole circle while the
   source was still sized for a toolbar that round does not have. */
var AREA_H = (typeof UI !== 'undefined' && UI.isRound && UI.isRound())
  ? gfx.height() : gfx.height() - 40;

var HAVE_CV = typeof sys !== 'undefined' && typeof sys.canvasTarget === 'function' &&
              typeof gfx.blit === 'function' && sys.canvas(0, gfx.width(), AREA_H) === 1;

var BG = 0x10141b;

function clearCanvas() {
  if (!HAVE_CV) { UI.set({ strokes: [] }); return; }
  sys.canvasTarget(0);
  gfx.clear(BG);
  sys.canvasTarget(-1);
  UI.set({ cleared: (UI.state.cleared || 0) + 1 });
}
if (HAVE_CV) clearCanvas();

/* round-join thick stroke out of public gfx: segment quads + joint dots */
function strokeInto(pts, color, w) {
  var r = w / 2;
  for (var i = 0; i < pts.length; i++) {
    var p = pts[i];
    gfx.circle(Math.round(p.x), Math.round(p.y), Math.max(1, Math.round(r)), color, 1);
    if (i === 0) continue;
    var a = pts[i - 1], dx = p.x - a.x, dy = p.y - a.y;
    var len = Math.sqrt(dx * dx + dy * dy);
    if (len < 0.01) continue;
    var nx = (-dy / len) * r, ny = (dx / len) * r;
    gfx.poly([[{ x: a.x + nx, y: a.y + ny }, { x: p.x + nx, y: p.y + ny },
               { x: p.x - nx, y: p.y - ny }, { x: a.x - nx, y: a.y - ny }]], color, 'nonzero');
  }
}

function commit(st) {
  if (!HAVE_CV) {
    var ss = (UI.state.strokes || []).slice();
    ss.push(st);
    UI.set({ strokes: ss });
    return;
  }
  sys.canvasTarget(0);
  strokeInto(st.pts, st.color, st.w);
  sys.canvasTarget(-1);   /* gen bump: the blit repaints, the JPEG re-sends */
}

var COLORS = [0x44dd88, 0xff6b6b, 0x4a9dff, 0xffd166, 0xffffff];

function App() {
  var color = UI.state.color === undefined ? COLORS[0] : UI.state.color;
  var live = UI.state.liveStroke || null;
  /* Round glass: the canvas is the WHOLE circle and the controls ride the
     rim on an ArcFooter, so nothing square is cut off and no strip of
     drawing surface is spent on a toolbar. AREA_H is shared with the
     source allocation above -- they must never disagree. */
  var round = UI.isRound();
  var areaH = AREA_H;

  var chips = [];
  for (var i = 0; i < COLORS.length; i++) {
    chips.push(h('box', {
      w: 26, h: 26, radius: 13, bg: COLORS[i],
      border: color === COLORS[i] ? 0xffffff : 0x333a46, borderW: 2,
      onTap: (function (c2) { return function () { UI.set({ color: c2 }); }; })(COLORS[i])
    }));
  }
  chips.push(h(Button, {
    label: 'CLEAR', size: 1, pad: em(0.5), bg: UI.theme.panel,
    onTap: function () { clearCanvas(); }
  }));
  /* DIRECT: no live polyline layer -- every move rasterizes its segment
     straight into the canvas, and the frame is just the blit */
  chips.push(h(Button, {
    label: 'DIRECT', size: 1, pad: em(0.5),
    bg: UI.state.direct ? UI.theme.accent : UI.theme.panel,
    onTap: function () { UI.set({ direct: UI.state.direct ? 0 : 1 }); }
  }));

  /* The same controls as items on the arc: round swatches climb the rim
     happily (a circle has no orientation to get wrong), and the two word
     buttons sit nearest bottom-centre where the chord is widest. */
  var arcItems = [];
  arcItems.push({ w: 40, h: 22, node: h(Button, {
    label: 'CLR', size: 1, pad: em(0.25), w: 40, h: 22, bg: UI.theme.panel,
    onTap: function () { clearCanvas(); }
  }) });
  for (var ai = 0; ai < COLORS.length; ai++) {
    arcItems.push({ w: 24, h: 24, node: h('box', {
      w: 24, h: 24, radius: 12, bg: COLORS[ai], hitPad: 4,
      border: color === COLORS[ai] ? 0xffffff : 0x333a46, borderW: 2,
      onTap: (function (c2) { return function () { UI.set({ color: c2 }); }; })(COLORS[ai])
    }) });
  }
  arcItems.push({ w: 46, h: 22, node: h(Button, {
    label: 'DIR', size: 1, pad: em(0.25), w: 46, h: 22,
    bg: UI.state.direct ? UI.theme.accent : UI.theme.panel,
    onTap: function () { UI.set({ direct: UI.state.direct ? 0 : 1 }); }
  }) });

  var layers = [
    HAVE_CV
      ? h('canvas', { src: 0, w: gfx.width(), h: areaH })
      : h('box', { w: gfx.width(), h: areaH, bg: BG },
          (UI.state.strokes || []).map(function (st) {
            return h('path', { pts: st.pts, color: st.color, w: st.w });
          }))
  ];
  if (live) {
    layers.push(h('abs', { x: 0, y: 0 },
      h('path', { pts: live.pts, color: live.color, w: live.w })));
  }

  return (
    <box h={gfx.height()}>
      <box h={areaH} clip={true}
           onDraw={function (phase, x, y, id) {
             if (UI.state.direct && HAVE_CV) {
               /* straight into the bitmap, one segment per move */
               var lp = UI.state._dl;
               var pt = { x: x, y: y };
               sys.canvasTarget(0);
               strokeInto(lp && phase !== 0 ? [lp, pt] : [pt], color, 4);
               sys.canvasTarget(-1);
               UI.set({ _dl: phase === 2 ? null : pt,
                        liveTick: (UI.state.liveTick || 0) + 1 });
               return;
             }
             var st = UI.state.liveStroke;
             if (phase === 0) {
               UI.set({ liveStroke: { pts: [{ x: x, y: y }], color: color, w: 4 } });
             } else if (st) {
               st.pts.push({ x: x, y: y });
               if (phase === 2) {
                 commit(st);
                 UI.set({ liveStroke: null });
               } else {
                 UI.set({ liveTick: (UI.state.liveTick || 0) + 1 });
               }
             }
           }}>
        {h('box', {}, layers)}
      </box>
      {round
        ? h(ArcFooter, { items: arcItems, spread: 150, inset: 10 })
        : h('row', { h: 40, pad: 6, gap: 8, bg: UI.theme.panel }, chips)}
    </box>
  );
}

UI.mount(App);

/*
 * A stateful example: tap the button, the count changes, the screen
 * redraws to match. Proves the actual point of the framework — no
 * reconciler, no retained tree, state -> UI.set -> full redraw — not just
 * that boxes can be laid out.
 *
 * Only one tappable control on purpose: the pure-js runner drives a real
 * simulated touch (not a direct function call) by reading UI._hits[0]
 * after the first render, and a single control keeps that unambiguous
 * without hardcoding screen coordinates that would silently rot if the
 * layout above it changed.
 */
function App() {
  var count = UI.state.count || 0;
  return (
    <box pad={em(2)} gap={em(2)}>
      <text text={'COUNT: ' + count} size={3} color={UI.theme.text} align="center" />
      <Button label="+1" size={2}
              onTap={function () { UI.set({ count: count + 1 }); }} />
    </box>
  );
}

UI.mount(App);

module.exports.demo = function (UI, backend) {
  var hit = UI._hits[0];
  if (!hit) { console.error('no tappable control found after first render'); return; }
  var x = hit.x + 4, y = hit.y + 4;
  UI.pointer(0, 0, x, y); // pointer id 0, phase 0 = press
  UI.pointer(0, 2, x, y); // release -> tap -> onTap -> UI.set({count: 1})
  console.log('simulated tap at ' + x + ',' + y + ' -> count is now ' + UI.state.count);
};

/*
 * Freehand drawing with tools - the onDraw capture control in action.
 * The canvas owns every stroke that starts inside it (press/move/release,
 * local coordinates, per-pointer id so multitouch draws independent
 * shapes); palette, tools and CLEAR stay ordinary tappable controls, and
 * the width slider is its own capture area. Shapes drag with LIVE
 * preview: rect and circle resize until release, pen simplifies its
 * points (Ramer-Douglas-Peucker) when the stroke ends. Everything renders
 * as path nodes - the circle is a 24-gon path, so stroke width and round
 * joins work the same for every tool.
 */
function shapePts(sh) {
  if (sh.tool === 'pen') return sh.pts;
  var a = sh.a, b = sh.b;
  if (sh.tool === 'line') return [a, b];
  if (sh.tool === 'rect') return [a, { x: b.x, y: a.y }, b, { x: a.x, y: b.y }];
  /* circle: centre a, radius to b, as a 24-gon */
  var dx = b.x - a.x, dy = b.y - a.y;
  var r = Math.sqrt(dx * dx + dy * dy);
  var pts = [];
  for (var i = 0; i < 24; i++) {
    var an = (i * 2 * Math.PI) / 24;
    pts.push({ x: a.x + Math.cos(an) * r, y: a.y + Math.sin(an) * r });
  }
  return pts;
}

function App() {
  var strokes = UI.state.strokes || [];
  var sc = UI.state.sc === undefined ? 0x44dd88 : UI.state.sc;   /* stroke colour, null = none */
  var fc = UI.state.fc === undefined ? null : UI.state.fc;       /* fill colour, null = none */
  var slot = UI.state.slot || 'sc';                              /* which slot the palette edits */
  var tool = UI.state.tool || 'pen';

  function markFor(st) {
    var closed = st.tool === 'rect' || st.tool === 'circle';
    return <path pts={shapePts(st)}
                 color={st.sc === null ? undefined : st.sc}
                 w={st.w || 2}
                 close={closed}
                 join={st.tool === 'rect' ? 'miter' : undefined}
                 fill={st.fc === null ? undefined : st.fc} />;
  }
  /* Strokes still being drawn mutate IN PLACE inside the strokes array,
     so the memo covers only the ones below the lowest live index --
     those are final. Reused path nodes then replay their cached stroke
     geometry instead of re-running the outliner (see the path node),
     which is what keeps a canvas with many finished shapes cheap while
     the pen is moving. */
  var liveMap = UI.state.live || {};
  var liveMin = strokes.length;
  for (var lk in liveMap) {
    if (liveMap[lk] < liveMin) liveMin = liveMap[lk];
  }
  var finished = UI.memo('drawFinished', [strokes, liveMin], function () {
    var ms = [];
    for (var si = 0; si < liveMin; si++) ms.push(markFor(strokes[si]));
    return h('box', {}, ms);
  });
  /* The LIVE stroke renders plainly every frame. It was briefly frozen
     into memoized chunks for speed, but memo deps over mutating stroke
     state proved impossible to get right (a cleared canvas's next
     stroke matched the old keys and REPLAYED OLD INK) -- and the honest
     measurement said the win was small. Finished strokes carry the
     optimization instead: their content is immutable, so the memo above
     and the path geometry cache are safe there. */
  var marks = [finished];
  for (var si2 = liveMin; si2 < strokes.length; si2++) marks.push(markFor(strokes[si2]));

  var previewC = sc !== null ? sc : (fc !== null ? fc : 0x555555);
  var tools = ['pen', 'line', 'rect', 'circle'];
  var toolBtns = [];
  for (var ti = 0; ti < tools.length; ti++) {
    toolBtns.push(
      <Button label={tools[ti].toUpperCase()} size={1} pad={em(0.4)}
              bg={tools[ti] === tool ? 0x2e4a37 : undefined}
              color={tools[ti] === tool ? 0x9fe8b9 : undefined}
              onTap={(function (t) { return function () { UI.set({ tool: t }); }; })(tools[ti])} />
    );
  }
  toolBtns.push(
    <Button label="CLR" size={1} pad={em(0.4)} color={0xdd6644}
            onTap={function () { UI.set({ strokes: [] }); }} />
  );


  /* slot chips: which colour the palette edits - S(troke) or F(ill).
     The chip shows its slot's current colour; X in the palette sets the
     active slot to transparent. */
  function chip(label, key, val) {
    return (
      <box w={em(2.2)} h={em(2.2)} bg={val === null ? 0x14161b : val} radius={4}
           border={slot === key ? 0xffffff : 0x3a4152} borderW={slot === key ? 2 : 1}
           onTap={function () { UI.set({ slot: key }); }}>
        <text text={val === null ? label + 'x' : label} size={1} align="center"
              color={val === null || val === 0x000000 || val === 0xdd6644 ? 0xaaaaaa : 0x222222} />
      </box>
    );
  }
  var colors = [0x44dd88, 0x66aaff, 0xffcc44, 0xdd6644, 0xffffff, 0x000000];
  var active = slot === 'sc' ? sc : fc;
  var pal = [chip('S', 'sc', sc), chip('F', 'fc', fc)];
  for (var ci = 0; ci < colors.length; ci++) {
    pal.push(
      <box w={em(2)} h={em(2.2)} bg={colors[ci]} radius={4}
           border={colors[ci] === active ? 0xffffff : 0x3a4152} borderW={colors[ci] === active ? 2 : 1}
           onTap={(function (c) { return function () { var o = {}; o[UI.state.slot || 'sc'] = c; UI.set(o); }; })(colors[ci])} />
    );
  }
  pal.push(
    <box w={em(2)} h={em(2.2)} bg={0x14161b} radius={4}
         border={active === null ? 0xffffff : 0x3a4152} borderW={active === null ? 2 : 1}
         onTap={function () { var o = {}; o[UI.state.slot || 'sc'] = null; UI.set(o); }}>
      <text text="x" size={1} align="center" color={0xdd6644} />
    </box>
  );

  var drawSurface = (
      <box flex={1} bg={0x14161b} clip={true}
           onDraw={function (phase, x, y, id) {
             var st2 = UI.state.strokes || [];
             var live = UI.state.live || {};
             var tl = UI.state.tool || 'pen';
             if (phase === 0) {
               live[id] = st2.length;
               var sh = { tool: tl,
                          sc: UI.state.sc === undefined ? 0x44dd88 : UI.state.sc,
                          fc: UI.state.fc === undefined ? null : UI.state.fc,
                          w: UI.state.width || 2 };
               if (tl === 'pen') sh.pts = [{ x: x, y: y }];
               else { sh.a = { x: x, y: y }; sh.b = { x: x, y: y }; }
               st2 = st2.concat([sh]);
             } else if (live[id] !== undefined && st2[live[id]]) {
               var cur = st2[live[id]];
               if (cur.tool === 'pen') {
                 var last = cur.pts[cur.pts.length - 1];
                 var dx = x - last.x, dy = y - last.y;
                 if (dx * dx + dy * dy >= 4 || phase === 2) cur.pts.push({ x: x, y: y });
                 if (phase === 2) cur.pts = UI.simplifyPath(cur.pts, 1.4);
               } else {
                 cur.b = { x: x, y: y }; /* live resize until release */
               }
               if (phase === 2) delete live[id];
             }
             UI.set({ strokes: st2, live: live });
           }}>
        {marks}
      </box>
  );

  /* ROUND: the canvas takes the whole circle and the palette rides the
     bottom arc -- round swatches climb the rim (a circle doesn't care
     what angle it sits at), the tool cycler and CLEAR sit nearest
     bottom-centre where the chord is widest. No slider, no S/F chips:
     a watch face gets the fun parts. */
  if (UI.isRound()) {
    var items = [];
    items.push({ w: 38, h: 22, node:
      <Button label={tool.toUpperCase()} size={1} pad={em(0.25)} h={22} w={38}
              bg={0x2e4a37} color={0x9fe8b9}
              onTap={function () {
                var cur = UI.state.tool || 'pen', ni = 0;
                for (var k = 0; k < tools.length; k++) if (tools[k] === cur) ni = (k + 1) % tools.length;
                UI.set({ tool: tools[ni] });
              }} /> });
    /* WHICH slot the swatches paint -- stroke or fill. Without this the
       swatches always wrote the stroke colour and a fill could not be
       chosen at all: the round layout had the palette but not the thing
       that says what the palette is FOR. */
    items.push({ w: 26, h: 22, node:
      <box w={26} h={22} radius={5} hitPad={4}
           bg={slot === 'sc' ? (sc === null ? 0x14161b : sc)
                             : (fc === null ? 0x14161b : fc)}
           border={0xffffff} borderW={1}
           onTap={function () { UI.set({ slot: slot === 'sc' ? 'fc' : 'sc' }); }}>
        <text text={slot === 'sc' ? 'S' : 'F'} size={1} align="center"
              color={(slot === 'sc' ? sc : fc) === null ? 0xaaaaaa : 0x222222} />
      </box> });
    for (var ri = 0; ri < colors.length; ri++) {
      items.push({ w: 22, h: 22, node:
        <box w={22} h={22} bg={colors[ri]} radius={11} hitPad={4}
             border={colors[ri] === active ? 0xffffff : 0x3a4152}
             borderW={colors[ri] === active ? 2 : 1}
             onTap={(function (c) { return function () { var o = {}; o[UI.state.slot || 'sc'] = c; UI.set(o); }; })(colors[ri])} /> });
    }
    items.push({ w: 22, h: 22, node:
      <box w={22} h={22} bg={0x14161b} radius={11} hitPad={4}
           border={active === null ? 0xffffff : 0x3a4152} borderW={active === null ? 2 : 1}
           onTap={function () { var o = {}; o[UI.state.slot || 'sc'] = null; UI.set(o); }}>
        <text text="x" size={1} align="center" color={0xdd6644} />
      </box> });
    items.push({ w: 34, h: 22, node:
      <Button label="CLR" size={1} pad={em(0.25)} h={22} w={34} color={0xdd6644}
              onTap={function () { UI.set({ strokes: [] }); }} /> });
    return (
      <box h={gfx.height()}>
        {drawSurface}
        {h(ArcFooter, { items: items, spread: 150, inset: 10 })}
      </box>
    );
  }

  return (
    <box h={gfx.height()}>
      <box bg={0x223048} pad={em(0.5)} h={em(2.6)}>
        <text text={'DRAW - ' + strokes.length + ' shapes'} size={1} align="center" color={0x8fb8ff} />
      </box>

      {drawSurface}

      <box bg={0x223048} pad={em(0.5)} h={em(9)} gap={em(0.4)}>
        <row gap={em(0.4)}>{toolBtns}</row>
        <row gap={em(0.5)}>{pal}</row>
        <box bg={0x14161b} radius={6} h={em(1.8)} pad={em(0.25)} hitPad={4} vcenter={true}
             onDraw={function (phase, x) {
               var trackW = gfx.width() - em(1);
               var w2 = 1 + Math.max(0, Math.min(1, x / trackW)) * 7;
               UI.set({ width: Math.round(w2) });
             }}>
          <box w={Math.max(em(0.8), Math.round((((UI.state.width || 2) - 1) / 7) * (gfx.width() - em(1.5))))}
               bg={previewC} radius={2} h={UI.state.width || 2} />
        </box>
      </box>
    </box>
  );
}

UI.mount(App);

/*
 * Direct pin access through sys.gpio(pin, op, value):
 *   op 0 reads (the firmware sets INPUT_PULLUP first, so an open pin reads 1)
 *   op 1 writes (sets OUTPUT, drives value)
 *   op 2 reads the ADC
 * The firmware refuses pins the active board's display or touch controller
 * own and answers -1; that refusal is shown here rather than hidden.
 *
 * Reading reconfigures the pin (INPUT_PULLUP), so while DRIVE is selected
 * this app stops polling — otherwise every tick would release the pin it
 * just drove.
 *
 * On hosts without the native (browser, sim, terminal, the gallery
 * renderer) a SIMULATED board stands in — see simGpio below — so the whole
 * flow stays clickable and self-checkable anywhere. Every call goes
 * through gpio(); when the native exists that is a straight pass-through
 * and this page behaves exactly as it does on the bridge.
 */
var HAVE = typeof sys !== 'undefined' && typeof sys.gpio === 'function';

/* ---- the no-hardware board -------------------------------------------
 * An UNWIRED board, modelled off the 1.69" 240x280 build (BOARD 1 in
 * docs/hardware-api.md): its display and touch pins answer -1 exactly as
 * the firmware's denylist does, every other pin is open so a read sees
 * the pullup (1), a write reports the 1 the native reports, and the ADC
 * gives a stable per-pin count — an unconnected analog pin floats, and a
 * fixed number is the version of that a headless render can reproduce
 * frame to frame. Nothing here reads a clock, on purpose: the gallery
 * PNG and the golden hashes must not move between runs.
 *
 * The one value this board cannot show you is a genuine LOW — nothing is
 * pulling any pin down. That needs the real thing.
 */
var SIM_REFUSED = [4, 5, 6, 7, 8, 10, 11, 13, 14, 15];

function simRefused(p) {
  for (var i = 0; i < SIM_REFUSED.length; i++) {
    if (SIM_REFUSED[i] === p) return true;
  }
  return false;
}

function simGpio(p, op, value) {
  if (simRefused(p)) return -1;
  if (op === 1) return 1;                       /* write: OUTPUT, driven */
  if (op === 2) return (p >= 1 && p <= 20) ? (p * 173) % 4096 : 0;
  if (op === 0) return 1;                       /* INPUT_PULLUP, open pin */
  return -1;                                    /* unknown op, as firmware */
}

/* The single door to the hardware. Same argument order, same return
   codes, so nothing below this line knows which board it is talking to.
   A read is forwarded as TWO arguments, never as a third `undefined`:
   "value omitted" is how the native is told this is a read, and handing
   it an explicit undefined would arrive as a write of 0. */
function gpio(p, op, value) {
  if (!HAVE) return simGpio(p, op, value);
  if (value === undefined) return sys.gpio(p, op);
  return sys.gpio(p, op, value);
}

function pin() { return UI.state.pin === undefined ? 16 : UI.state.pin; }
function mode() { return UI.state.mode || 'read'; }

function step(d) {
  var p = pin() + d;
  if (p < 0) p = 0;
  if (p > 48) p = 48;
  UI.set({ pin: p, val: null, level: 0, mode: mode() === 'drive' ? 'read' : mode() });
}

function setMode(m) {
  UI.set({ mode: m, val: null });
  if (m === 'drive') UI.set({ level: 0, val: gpio(pin(), 1, 0) });
}

function toggle() {
  var lv = UI.state.level ? 0 : 1;
  UI.set({ level: lv });
  UI.set({ val: gpio(pin(), 1, lv) });
}

/* Poll only in the reading modes; renders come free when nothing changed. */
UI.onTick = function () {
  if (mode() === 'drive') return;
  var v = gpio(pin(), mode() === 'adc' ? 2 : 0);
  if (v !== UI.state.val) UI.set({ val: v });
};

function valueLine() {
  var v = UI.state.val;
  if (v === null || v === undefined) return '...';
  if (v === -1) return 'refused (display/touch pin)';
  if (mode() === 'adc') return 'adc ' + v;
  if (mode() === 'drive') return 'driving ' + (UI.state.level ? 'HIGH' : 'LOW');
  return v ? 'HIGH (1)' : 'LOW (0)';
}

function ModeBtn(props) {
  return h(Button, {
    label: props.label, size: 1, flex: 1,
    bg: mode() === props.m ? UI.theme.accent : UI.theme.panel,
    onTap: function () { setMode(props.m); }
  });
}

function App() {
  return (
    <box h={gfx.height()} scroll="gpio" pad={em(1)} gap={em(0.75)}>
      <text text="GPIO" size={2} align="center" color={UI.theme.accent} />
      {HAVE ? null : <text text="simulated - no gpio native" size={1} align="center"
                           color={UI.theme.warn} />}

      <row gap={em(0.5)} align="center">
        <Button label="-" size={2} onTap={function () { step(-1); }} />
        <text text={'PIN ' + pin()} size={2} flex={1} align="center"
              color={UI.theme.text} />
        <Button label="+" size={2} onTap={function () { step(1); }} />
      </row>

      <row gap={em(0.5)}>
        <ModeBtn label="READ" m="read" />
        <ModeBtn label="ANALOG" m="adc" />
        <ModeBtn label="DRIVE" m="drive" />
      </row>

      <box bg={UI.theme.panel} radius={8} pad={em(1.25)} gap={em(0.5)}>
        <text text={mode() === 'drive' ? 'output' : 'live ' + mode()}
              size={1} color={UI.theme.muted} />
        <text text={valueLine()} size={2}
              color={UI.state.val === -1 ? UI.theme.warn : UI.theme.ok} />
      </box>

      {mode() === 'drive' ?
        <Button label={UI.state.level ? 'SET LOW' : 'SET HIGH'} size={2}
                bg={UI.theme.accent} onTap={toggle} /> : null}
    </box>
  );
}

UI.mount(App);
/* Seed the first frame on a simulated board so a single-frame render (the
   gallery, a golden) shows a live reading rather than '...'. The native
   path is left untouched: there, the first tick does the first read, as
   it always has. */
if (!HAVE) UI.set({ val: gpio(pin(), 0) });

/*
 * The smallest real mjsx app: a panel, a border, some centred text.
 * Written the way it would be on a chip — h and UI are ambient globals,
 * no imports — because that's the actual contract mjsx-core makes.
 */
function App() {
  return (
    <box pad={em(2)} gap={em(1.5)}>
      <box bg={UI.theme.panel} radius={8} border={UI.theme.accent} borderW={2}
           pad={em(1.5)}>
        <text text="Hello mjsx!" size={2} color={UI.theme.text} align="center" />
      </box>
      <text text="one core. esp32, pi, node, browser." size={1}
            color={UI.theme.muted} align="center" wrap={true} />
    </box>
  );
}

UI.mount(App);

/*
 * Bus scan and register peek through sys.i2c(addr, reg, value):
 * value < 0 (or omitted) reads one byte of that register, value >= 0
 * writes one — the same write-reg-then-repeated-start-read the bridge's
 * `reg` TCP command does. -1 means no answer.
 *
 * The scan probes 8..119 by reading register 0 of each address, a few
 * per tick so the UI stays live while it walks the bus. Tap a responder
 * to peek registers 0..15. Peeking is a read like any other: some
 * devices clear interrupt flags on read, so a peek is not always free.
 *
 * On hosts without the native (browser, sim, terminal) the page says so
 * instead of crashing.
 *
 * LAYOUT, and why it is the way it is: the page is a FIXED-HEIGHT FLEX
 * COLUMN, not a scroll viewport. Only that shape makes the address list
 * work -- `flex` is honoured by a pinned-height box that is not itself
 * scrolling, and `scroll` becomes a real viewport only once a parent
 * hands the box a height. Making the PAGE the scroller instead (which
 * this example used to do) silently kills both on the list: it lays out
 * at its full natural height, the register panel it is supposed to share
 * the screen with is pushed off the bottom -- on a short or round panel
 * the viewport culls the panel entirely, so it is never drawn at all --
 * and a tap on a row looks like it did nothing. The peek fired; there
 * was just nowhere on the glass for it to land.
 */
var HAVE = typeof sys !== 'undefined' && typeof sys.i2c === 'function';

function hex(n) {
  var s = n.toString(16).toUpperCase();
  return s.length < 2 ? '0' + s : s;
}

function startScan() {
  if (!HAVE) return;
  UI.set({ found: [], next: 8, sel: null, regs: null });
}

/* A few addresses per tick: a missing device NACKs fast, but 112 probes
   in one tap would still stall a frame noticeably. */
UI.onTick = function () {
  var next = UI.state.next;
  if (!HAVE || next === undefined || next === null) return;
  var found = UI.state.found || [];
  var stop = next + 8;
  for (; next < stop && next <= 119; next++) {
    if (sys.i2c(next, 0) >= 0) found = found.concat([next]);
  }
  UI.set({ found: found, next: next > 119 ? null : next });
};

function peek(addr) {
  var regs = [];
  for (var r = 0; r < 16; r++) regs.push(sys.i2c(addr, r));
  UI.set({ sel: addr, regs: regs });
}

function regRows() {
  var rows = [];
  var regs = UI.state.regs || [];
  for (var r = 0; r < 4; r++) {
    var line = '';
    for (var c = 0; c < 4; c++) {
      var i = r * 4 + c;
      line += hex(i) + ':' + (regs[i] < 0 ? '--' : hex(regs[i])) + '  ';
    }
    rows.push(<text text={line} size={1} color={UI.theme.text} />);
  }
  return rows;
}

function App() {
  var found = UI.state.found || [];
  var scanning = UI.state.next !== undefined && UI.state.next !== null;

  var kids = [
    <text text="I2C SCAN" size={2} align="center" color={UI.theme.accent} />
  ];

  if (!HAVE) {
    kids.push(<text text="host has no i2c" size={1} align="center"
                    color={UI.theme.warn} />);
  } else {
    kids.push(<Button label={scanning ? 'SCANNING ' + UI.state.next + '...' : 'SCAN'}
                      size={2} onTap={startScan} />);
    if (!scanning && UI.state.found) {
      kids.push(<text text={found.length + ' responding'} size={1}
                      align="center" color={UI.theme.muted} />);
    }
  }

  var list = [];
  for (var i = 0; i < found.length; i++) {
    list.push(h(Button, {
      label: '0x' + hex(found[i]) + '  (' + found[i] + ')',
      size: 1, pad: em(0.6),
      bg: UI.state.sel === found[i] ? UI.theme.accent : UI.theme.panel,
      onTap: (function (a) { return function () { peek(a); }; })(found[i])
    }));
  }
  /* The list takes whatever the fixed rows above and the register panel
     leave over, and scrolls INSIDE that -- so the panel stays on screen
     however many devices answer. */
  var listBox = h('box', { flex: 1, scroll: 'addrs', gap: em(0.4) }, list);

  var panel = null;
  if (UI.state.regs) {
    panel = (
      <box bg={UI.theme.panel} radius={8} pad={em(1)} gap={em(0.3)}>
        <text text={'0x' + hex(UI.state.sel) + ' registers 0..15'}
              size={1} color={UI.theme.muted} />
        {regRows()}
      </box>
    );
  }

  /* Square glass: the panel sits under the list, so opening it only
     shortens the list from the bottom and the row under the finger stays
     put. Round glass has no room down there -- a full-width register row
     runs straight into the rim -- so the panel takes the wide middle and
     the LIST, which scrolls anyway, gets the narrow arc. */
  if (panel && UI.isRound()) {
    kids.push(panel);
    kids.push(listBox);
  } else {
    kids.push(listBox);
    if (panel) kids.push(panel);
  }

  return h('box', { h: gfx.height(), pad: em(1), gap: em(0.6) }, kids);
}

UI.mount(App);
if (HAVE) startScan();

/*
 * Text input, every way in at once.
 *
 * - Physical keyboard: just type — printable keys insert, Backspace/
 *   arrows/Home/End edit, Tab / shift-Tab walk the fields (scrolling
 *   them into view), Enter submits, Esc blurs.
 * - Touch: tap places the caret, a drag scrolls overflowing text
 *   sideways, press-and-hold then drag walks the caret under the finger.
 * - The framework's virtual keyboard: four layouts — QWERTY (shift +
 *   symbols page), T9 multi-tap, a number pad, and STRIP: a single
 *   scrolling row of characters (drag to scroll, tap to type) for
 *   displays with no room for a grid.
 * - A CUSTOM keyboard is nothing special: the PIN field below brings up
 *   PinPad, ordinary JSX whose taps call UI.type()/UI.key(). A host can
 *   also present a native keyboard entirely outside the JS VM (the http
 *   backend summons the phone's real one) — keystrokes all arrive the
 *   same way.
 */

/* AUTO first, and the default: it fits the layout to the glass (QWERTY
   where ten columns fit, T9 where four do, STRIP below that). The named
   ones are honoured exactly however cramped -- pick one on a small screen
   to see the difference. */
var LAYOUTS = ['auto', 'qwerty', 't9', 'numbers', 'strip'];

function Field(p) {
  return (
    <box gap={2}>
      <text text={p.label} size={1} color={UI.theme.muted} />
      <input id={p.id} size={p.size || 2} placeholder={p.placeholder}
             password={p.password} maxLen={p.maxLen}
             label={p.label} exclusive={p.exclusive}
             onSubmit={function (v) { UI.set({ last: p.label + ': ' + v }); }} />
    </box>
  );
}

/* A user-supplied keyboard: plain JSX, no registration. Digits go in with
   UI.type, the rest are the same named keys a physical board sends. */
function PinPad() {
  var rows = [['1', '2', '3'], ['4', '5', '6'], ['7', '8', '9'], ['DEL', '0', 'OK']];
  var kids = [];
  for (var r = 0; r < rows.length; r++) {
    var ks = [];
    for (var c = 0; c < 3; c++) {
      ks.push(h(Button, {
        label: rows[r][c], size: 2, pad: em(0.75),
        bg: rows[r][c] === 'OK' ? UI.theme.accent
          : rows[r][c] === 'DEL' ? UI.theme.panel : UI.theme.key,
        onTap: (function (k) {
          return function () {
            if (k === 'DEL') UI.key('press', 'Backspace');
            else if (k === 'OK') UI.key('press', 'Enter');
            else UI.type(k);
          };
        })(rows[r][c])
      }));
    }
    kids.push(h('row', { gap: 2 }, ks));
  }
  return h('box', { bg: UI.theme.panel, pad: 4, gap: 2 }, kids);
}

var POSITIONS = ['bottom', 'top', 'inline'];

function App() {
  var kb = UI.state.kb || 'auto';
  var pos = UI.state.kbPos || 'bottom';
  var focused = UI.focused();

  var chips = [];
  for (var i = 0; i < LAYOUTS.length; i++) {
    chips.push(h(Button, {
      label: LAYOUTS[i].toUpperCase(), size: 1, pad: em(0.6),
      bg: kb === LAYOUTS[i] ? UI.theme.accent : UI.theme.key,
      onTap: (function (l) { return function () { UI.set({ kb: l }); }; })(LAYOUTS[i])
    }));
  }
  /* where the keyboard docks: bottom/top overlay the page (an inset keeps
     revealed fields out from under them), inline flows like any child */
  chips.push(h(Button, {
    label: 'POS:' + pos.toUpperCase(), size: 1, pad: em(0.6), bg: UI.theme.panel,
    onTap: function () {
      UI.set({ kbPos: POSITIONS[(POSITIONS.indexOf(pos) + 1) % POSITIONS.length] });
    }
  }));

  /* The whole form reuses across frames: focus borders, carets and
     typed text are all DRAW-time reads, so typing and tabbing never
     rebuild it -- only the chip selections and the submit line do. */
  var form = UI.memo('inputForm', [kb, pos, UI.state.last], function () { return (
    <box flex={1} scroll="form" pad={em(1)} gap={em(0.75)}>
      <text text="virtual keyboard layout" size={1} color={UI.theme.muted} />
      {h('row', { gap: 4 }, chips)}
      <spacer h={2} />
      <Field id="name" label="NAME" placeholder="tap to type" />
      <Field id="email" label="EMAIL" placeholder="you@example.com" />
      <Field id="pin" label="PIN (custom PinPad keyboard)" password={true} maxLen={6} />
      <Field id="city" label="CITY" />
      <Field id="note" label="NOTE (long text scrolls in the field)" />
      <Field id="tag" label="TAG (tab reaches me below the fold)" />
      <Field id="full" label="FULL (exclusive: keyboard takes the display)" exclusive={true} />
      <text text={UI.state.last || 'enter submits: results show here'}
            size={1} color={UI.theme.ok} wrap={true} />
    </box>
  ); });
  var kids = [
    <text text="INPUT" size={2} align="center" color={UI.theme.accent} />,
    form
  ];
  if (focused) {
    /* height is a hint: the keys scale so the whole keyboard fits it */
    kids.push(focused === 'pin' ? h(PinPad, {})
            : h(Keyboard, { layout: kb, position: pos, height: Math.floor(gfx.height() / 2.6) }));
  }
  return h('box', { h: gfx.height() }, kids);
}

UI.mount(App);

/*
 * Layering / scrolling / cropping torture test:
 *
 *  - fixed header and footer with a flex scroll region between them - list
 *    content must crop cleanly at both boundaries while scrolling
 *  - a badge overlapping the header edge (abs, drawn after the header)
 *  - cards whose swatches overlap each other (abs inside a fixed box)
 *  - a floating action button drawn over the scrolling list (abs after the
 *    scroll box in tree order - later-drawn wins hits too, so it stays
 *    tappable wherever the list is)
 *  - a modal (UI.openModal) - drawn last, owns ALL input; everything under
 *    it must stop responding until closed
 */
function ListItem(p) {
  var picked = UI.state.picked === p.n;
  return (
    <box bg={picked ? 0x2e4a37 : UI.theme.panel} radius={6} pad={em(0.75)}
         border={picked ? 0x44dd88 : undefined}
         onTap={function () { UI.set({ picked: p.n }); }}>
      <text text={'Item ' + p.n + (picked ? ' *' : '')} size={1}
            color={picked ? 0x9fe8b9 : UI.theme.text} />
    </box>
  );
}

function App() {
  var kids = [];
  for (var i = 1; i <= 14; i++) {
    if (i === 4) {
      kids.push(
        <box bg={UI.theme.panel} radius={6} pad={em(0.75)} gap={em(0.5)}>
          <text text="wrapped: the quick brown fox jumps over the lazy dog while the list scrolls and crops" size={1} color={UI.theme.muted} wrap={true} />
        </box>
      );
    }
    kids.push(<ListItem n={i} />);
  }

  return (
    <box h={gfx.height()}>
      {/* fixed header */}
      <box bg={0x223048} pad={em(0.75)} h={em(3.4)}>
        <text text="LAYERS" size={2} align="center" color={0x8fb8ff} />
        <text text="fixed header - list crops under me" size={1} align="center" color={UI.theme.muted} />
      </box>

      {/* the scroll region takes whatever the header+footer leave */}
      <box flex={1} scroll="main" pad={em(0.75)} gap={em(0.5)}>
        {kids}
      </box>

      {/* fixed footer */}
      <box bg={0x223048} pad={em(0.6)} h={em(3)}>
        <row>
          <text text={'picked: ' + (UI.state.picked || '-')} size={1} color={UI.theme.text} />
          <Button label="MODAL" size={1} pad={em(0.4)}
                  onTap={function () { UI.openModal(SmallModal); }} />
        </row>
      </box>

      {/* badge overlapping the header/list boundary - drawn after both */}
      <abs x={gfx.width() - em(5.5)} y={em(2.4)}>
        <box w={em(5)} bg={0xdd6644} radius={99} pad={em(0.35)}>
          <text text="badge" size={1} align="center" color={0xffffff} />
        </box>
      </abs>

      {/* floating action button over the scrolling list */}
      <abs x={gfx.width() - em(4.6)} y={gfx.height() - em(7)}>
        <box w={em(4)} bg={0x44dd88} radius={99} pad={em(0.6)}
             onTap={function () { UI.set({ fab: (UI.state.fab || 0) + 1 }); }}>
          <text text={'+' + (UI.state.fab || 0)} size={1} align="center" color={0x0c2216} />
        </box>
      </abs>
    </box>
  );
}

function SmallModal() {
  return (
    <Modal>
      <text text="MODAL" size={2} align="center" color={0x8fb8ff} />
      <text text="small content centres vertically; margins are minimums" size={1}
            color={UI.theme.muted} wrap={true} />
      <Button label="TALL VERSION" size={1}
              onTap={function () { UI.openModal(TallModal); }} />
      <Button label="CLOSE" size={1}
              onTap={function () { UI.closeModal(); }} />
    </Modal>
  );
}

function TallModal() {
  var lines = [];
  for (var i = 1; i <= 24; i++) {
    lines.push(<text text={'scrolling modal line ' + i} size={1} color={UI.theme.text} />);
  }
  return (
    <Modal header={<text text="STICKY HEADER" size={2} align="center" color={0x8fb8ff} />}
           footer={<Button label="CLOSE (STICKY)" size={1}
                           onTap={function () { UI.closeModal(); }} />}>
      {lines}
    </Modal>
  );
}

UI.mount(App);

/*
 * Screen settings, in JSX: brightness, sleep timeout, and what sleeping
 * means (dim to readable, or dark). The natives do the real work and
 * persist to flash themselves — sys.backlight(pct),
 * sys.sleepAfter(secs, dim), sys.screen() to read it all back — this
 * view is just state and taps. Detected by METHOD (Bun injects node
 * builtins as globals, so typeof alone lies on desktop); without the
 * natives it runs as a demo so the layout develops anywhere.
 *
 * The brightness slider applies LIVE while dragging (throttled: every
 * native call writes NVS, and a drag shouldn't cost a hundred flash
 * writes), with the final value applied on release.
 */

var HAVE = typeof sys !== 'undefined' && typeof sys.backlight === 'function';

function readScreen() {
  if (!HAVE) return { bl: 80, sleep: 30, dim: true };
  try { return JSON.parse('' + sys.screen()); }
  catch (e) { return { bl: 80, sleep: 30, dim: true }; }
}

var boot = readScreen();
UI.set({ bl: boot.bl, sleep: boot.sleep, dim: boot.dim ? 1 : 0,
         rot: boot.rot || 0, scale: boot.scale || 4,
         fmode: boot.fmode !== undefined ? boot.fmode
              : (boot.fnative === false ? 0 : 1) });

function applyBacklight(pct) {
  if (HAVE) sys.backlight(pct);
}
function applySleep() {
  if (HAVE) sys.sleepAfter(UI.state.sleep, UI.state.dim);
}

/* No OFF chip: NEVER in the mode row is the off switch, so the times
   stay a clean row of their own -- narrow screens fit both rows. */
var SLEEPS = [[15, '15s'], [30, '30s'], [60, '1m'], [300, '5m'], [900, '15m']];

/* The render-scale mode, sys.fonts(0|1|2): PIXEL renders logical and
   upscales uniformly (chunky); NATIVE composes every op at panel
   resolution (device-pixel sharp); HD adds Scale2x/3x-smoothed glyphs
   on top -- rounded diagonals once the glyph scale reaches 2. */
var HAVE_FONTS = HAVE && typeof sys.fonts === 'function';
var FMODES = ['PIXEL', 'NATIVE', 'HD'];
function applyFonts(n) {
  if (HAVE_FONTS) sys.fonts(n);
  UI.set({ fmode: n });
}

/* Rotation is a native concern too: sys.rotate(0..3) turns the panel,
   canvas, and touch mapping as one and persists. The layout here reads
   gfx.width()/height() every render, so the very next frame after a tap
   lays out for the new orientation. */
var HAVE_ROT = HAVE && typeof sys.rotate === 'function';
/* word labels: the 5x7 face has no degree glyph, and PORT/LAND says more
   than a number anyway. The starred pair is the same orientation flipped. */
var ROTS = [[0, 'PORT'], [1, 'LAND'], [2, 'PORT*'], [3, 'LAND*']];
function applyRotate(r) {
  if (HAVE_ROT) sys.rotate(r);
}

/* Display scale: sys.view() takes quarters, so 4 is 1:1 and 8 doubles
   every logical pixel. Inset and shift ride along unchanged -- this row
   only turns the one dial. Everything relaid out next frame, and the
   scale chips sit above the fold so 2x can always reach its way back. */
var HAVE_VIEW = HAVE && typeof sys.view === 'function';
var SCALES = [[4, '1x'], [5, '1.2x'], [6, '1.5x'], [8, '2x']];
function applyScale(q) {
  if (!HAVE_VIEW) return;
  var cur = readScreen();
  sys.view(q, cur.inset || 0, cur.shiftx || 0, cur.shifty || 0);
}

function App() {
  var bl = UI.state.bl || 80;

  var scaleChips = [];
  for (var s = 0; s < SCALES.length; s++) {
    scaleChips.push(h(Button, {
      label: SCALES[s][1], size: 1, pad: em(0.5),
      bg: UI.state.scale === SCALES[s][0] ? UI.theme.accent : UI.theme.key,
      onTap: (function (q) {
        return function () {
          applyScale(q);
          UI.set({ scale: HAVE_VIEW ? (readScreen().scale || 4) : q });
        };
      })(SCALES[s][0])
    }));
  }

  var rotChips = [];
  for (var r = 0; r < ROTS.length; r++) {
    rotChips.push(h(Button, {
      label: ROTS[r][1], size: 1, pad: em(0.5),
      bg: UI.state.rot === ROTS[r][0] ? UI.theme.accent : UI.theme.key,
      onTap: (function (rr) {
        return function () {
          applyRotate(rr);
          /* read the truth back rather than assuming: the native side may
             clamp, and the panel can be rotated from outside this view */
          UI.set({ rot: HAVE_ROT ? (readScreen().rot || 0) : rr });
        };
      })(ROTS[r][0])
    }));
  }

  var sleepChips = [];
  for (var i = 0; i < SLEEPS.length; i++) {
    sleepChips.push(h(Button, {
      label: SLEEPS[i][1], size: 1, pad: em(0.5),
      bg: UI.state.sleep === SLEEPS[i][0] ? UI.theme.accent : UI.theme.key,
      onTap: (function (secs) {
        return function () { UI.set({ sleep: secs }); applySleep(); };
      })(SLEEPS[i][0])
    }));
  }

  return (
    <box h={gfx.height()} scroll="screen" pad={em(0.75)} gap={em(0.7)}>
      <text text="SCREEN" size={2} align="center" color={UI.theme.accent} />

      <box bg={UI.theme.panel} radius={6} pad={em(0.75)} gap={em(0.5)}>
        <row>
          <text text="BRIGHTNESS" size={1} color={UI.theme.muted} />
          <text text={bl + '%'} size={1} align="right" color={UI.theme.text} />
        </row>
        <box h={em(2.2)} bg={UI.theme.key} radius={8} clip={true}
             onDraw={function (phase, x, y, id) {
               /* the box is the slider: position -> percent, applied
                  live but at most every 150ms; the release is exact */
               var w = gfx.width() - em(3);
               var pct = Math.round((x / w) * 100);
               if (pct < 5) pct = 5;
               if (pct > 100) pct = 100;
               UI.set({ bl: pct });
               var now = sys.millis();
               if (phase === 2 || now - (UI.state._blAt || 0) > 150) {
                 UI.set({ _blAt: now });
                 applyBacklight(pct);
               }
             }}>
          <box w={Math.max(8, Math.floor((gfx.width() - em(3)) * bl / 100))}
               h={em(2.2)} bg={UI.theme.accent} radius={8} />
        </box>
      </box>

      <box bg={UI.theme.panel} radius={6} pad={em(0.75)} gap={em(0.5)}>
        <text text="SCALE" size={1} color={UI.theme.muted} />
        {h('row', { gap: 4 }, scaleChips.concat([
          h('box', { w: em(0.6) }),
          h(Button, { label: FMODES[UI.state.fmode] || 'NATIVE', size: 1, pad: em(0.5),
                      bg: UI.state.fmode ? UI.theme.accent : UI.theme.key,
                      onTap: function () { applyFonts(((UI.state.fmode || 0) + 1) % 3); } })
        ]))}
      </box>

      <box bg={UI.theme.panel} radius={6} pad={em(0.75)} gap={em(0.5)}>
        <text text="ROTATION" size={1} color={UI.theme.muted} />
        {h('row', { gap: 4 }, rotChips)}
      </box>

      <box bg={UI.theme.panel} radius={6} pad={em(0.75)} gap={em(0.5)}>
        <row>
          <text text="SLEEP" size={1} color={UI.theme.muted} />
          <text text="wakes on touch" size={1} align="right" color={0x555f6e} />
        </row>
        <row gap={4}>
          <Button label="NEVER" size={1} pad={em(0.5)}
                  bg={!UI.state.sleep ? UI.theme.accent : UI.theme.key}
                  onTap={function () { UI.set({ sleep: 0 }); applySleep(); }} />
          <Button label="DIM" size={1} pad={em(0.5)}
                  bg={UI.state.sleep && UI.state.dim ? UI.theme.accent : UI.theme.key}
                  onTap={function () {
                    UI.set({ dim: 1, sleep: UI.state.sleep || 30 });
                    applySleep();
                  }} />
          <Button label="DARK" size={1} pad={em(0.5)}
                  bg={UI.state.sleep && !UI.state.dim ? UI.theme.accent : UI.theme.key}
                  onTap={function () {
                    UI.set({ dim: 0, sleep: UI.state.sleep || 30 });
                    applySleep();
                  }} />
        </row>
        {h('row', { gap: 4 }, sleepChips)}
      </box>

      {HAVE ? null
        : <text text="demo mode - no panel to control here" size={1}
                align="center" color={0x555f6e} />}
    </box>
  );
}

UI.mount(App);

/*
 * Every motion sensor the host has, three ways to look at it.
 *
 *   LEVEL  gravity as a bubble drifting in rings, with a horizon line
 *          tilting by roll — the one view a round display renders better
 *          than a rectangle, because a circle is already the frame
 *   TRACE  the last few seconds of each axis as a sparkline, so a tap or
 *          a shake reads as a SHAPE instead of three twitching numbers
 *   DATA   the numbers, and what is absent, stated plainly
 *
 * The module pushes STATE PATCHES on its own schedule and only when a
 * reading actually moved, so this view never polls: it renders
 * UI.state.accel / .gyro / .temp / .mag and is redrawn when they change.
 * That is the whole subscription — sys.modCtl('imu','start') and then
 * ordinary state.
 *
 * On a host with no motion hardware (a browser, the terminal, the 1.47"
 * board, which genuinely has no IMU) the simulator below drives the same
 * state, so the example is developable anywhere and says plainly which
 * of the two you are looking at.
 */
var HAVE_IMU = typeof sys !== 'undefined' && typeof sys.modCtl === 'function' &&
               sys.modCtl('imu', 'start') === 1;

/* What the module found, so the page can name the part rather than
   guessing: {"addr":107,"imu":"QMI8658","mag":"none",...} */
var INFO = {};
if (HAVE_IMU && typeof sys.mods === 'function') {
  var raw = sys.mods();
  if (raw && raw.indexOf('QMI8658') >= 0) INFO.imu = 'QMI8658';
  var MAGS = ['QMC5883L', 'HMC5883L', 'LIS3MDL', 'MLX90393'];
  for (var mi = 0; mi < MAGS.length; mi++) {
    if (raw && raw.indexOf(MAGS[mi]) >= 0) { INFO.mag = MAGS[mi]; break; }
  }
}

var VIEWS = ['LEVEL', 'TRACE', 'DATA'];

/* Rolling history, kept OUTSIDE UI.state: it changes every sample and
   would otherwise be a fresh object per patch for no benefit. The views
   read it at draw time. */
var HIST_N = 48;
var hist = { x: [], y: [], z: [], last: null };
function pushSample(a) {
  /* Fed from the RENDER rather than a timer: a render is exactly when new
     data arrived (the module patches state only when a reading moved), so
     the trace advances with the signal and never depends on a second
     clock agreeing with the first. */
  if (!a || a === hist.last) return;
  hist.last = a;
  hist.x.push(a.x); hist.y.push(a.y); hist.z.push(a.z);
  if (hist.x.length > HIST_N) { hist.x.shift(); hist.y.shift(); hist.z.shift(); }
}

function fmt(v, d) {
  return (v === undefined || v === null) ? '--' : v.toFixed(d);
}

/* ---- LEVEL -----------------------------------------------------------
 * Gravity as a bubble, rings for reference, and a horizon line tilting by
 * roll -- the one view a round display renders better than a rectangle.
 *
 * TWO things this had to learn the hard way. First, `abs` is PAGE
 * absolute, not parent relative: a dial drawn at box coordinates and
 * "centred" by flex spacers lands wherever the page origin is, which is
 * not the middle of anything. Every coordinate here is therefore
 * computed against gfx.width()/height() directly.
 *
 * Second, the IMU's axes are not the display's. Which way the chip is
 * rotated against the glass differs per board (and again per display
 * rotation), so there is no single correct mapping to hardcode -- TAP
 * THE DIAL to cycle the eight, and the choice is remembered per host in
 * configStorage. The bubble rolls to the LOW side, like a marble.
 */
var MAPS = [
  { n: 'x,y',   f: function (a) { return { x:  a.x, y:  a.y }; } },
  { n: 'x,-y',  f: function (a) { return { x:  a.x, y: -a.y }; } },
  { n: '-x,y',  f: function (a) { return { x: -a.x, y:  a.y }; } },
  { n: '-x,-y', f: function (a) { return { x: -a.x, y: -a.y }; } },
  { n: 'y,x',   f: function (a) { return { x:  a.y, y:  a.x }; } },
  { n: 'y,-x',  f: function (a) { return { x:  a.y, y: -a.x }; } },
  { n: '-y,x',  f: function (a) { return { x: -a.y, y:  a.x }; } },
  { n: '-y,-x', f: function (a) { return { x: -a.y, y: -a.x }; } }
];
/* Measured on the glass, not derived: the chip's X and Y are SWAPPED
   relative to the display. A flat board reads z = -1g so +Z points into
   the glass, and with the axes crossed that puts the chip's +X along the
   screen's vertical and +Y along its horizontal -- so the screen's x
   comes from -a.y and its y from -a.x. Boards whose chip sits rotated
   differently are one tap on the dial away. */
var MAP_DEFAULT = 7;   /* '-y,-x' */
function mapIdx() {
  var v = parseInt(configStorage.get('lvl.map', '' + MAP_DEFAULT), 10);
  return (isNaN(v) || v < 0 || v > 7) ? MAP_DEFAULT : v;
}

/* Returns the abs-positioned dial, drawn in PAGE coordinates. */
function tiltDeg(a) {
  if (!a) return null;
  var m = MAPS[mapIdx()].f(a);
  var mag = Math.sqrt(m.x * m.x + m.y * m.y);
  return Math.round(Math.asin(mag > 1 ? 1 : mag) * 180 / Math.PI);
}

function levelNodes(a, cx, cy, R) {
  var kids = [];
  var ring = UI.theme.panel;
  kids.push(h('abs', { x: cx - R, y: cy - R },
    h('circle', { r: R, color: ring, filled: false })));
  kids.push(h('abs', { x: cx - (R >> 1), y: cy - (R >> 1) },
    h('circle', { r: R >> 1, color: ring, filled: false })));
  kids.push(h('abs', { x: 0, y: 0 },
    h('line', { x1: cx - R, y1: cy, x2: cx + R, y2: cy, color: ring })));
  kids.push(h('abs', { x: 0, y: 0 },
    h('line', { x1: cx, y1: cy - R, x2: cx, y2: cy + R, color: ring })));
  if (!a) return kids;

  var m = MAPS[mapIdx()].f(a);
  /* horizon: the roll implied by the mapped lateral pull */
  var roll = Math.atan2(m.x, 1);
  var hx = Math.cos(roll) * R, hy = Math.sin(roll) * R;
  kids.push(h('abs', { x: 0, y: 0 },
    h('line', { x1: Math.round(cx - hx), y1: Math.round(cy - hy),
                x2: Math.round(cx + hx), y2: Math.round(cy + hy),
                color: UI.theme.accent, w: 2 })));

  var bx = m.x, by = m.y;
  var mag = Math.sqrt(bx * bx + by * by);
  if (mag > 1) { bx /= mag; by /= mag; }
  var br = Math.max(4, R >> 3);
  var lvl = mag < 0.05;
  kids.push(h('abs', { x: Math.round(cx + bx * (R - br) - br),
                       y: Math.round(cy + by * (R - br) - br) },
    h('circle', { r: br, color: lvl ? UI.theme.ok : UI.theme.warn, filled: true })));

  return kids;
}

/* ---- TRACE -----------------------------------------------------------
 * One sparkline per axis over the same vertical span, so their shapes
 * are comparable at a glance.
 */
function Trace(p) {
  var w = p.w, hgt = p.h, span = p.span;
  var kids = [];
  var mid = Math.floor(hgt / 2);
  /* NO abs here: abs is PAGE absolute and painted this graph over the
     header. `line` and `path` measure zero height, so as ordinary flow
     children they draw from THIS box's origin and stack correctly. */
  kids.push(h('line', { x1: 0, y1: mid, x2: w, y2: mid, color: UI.theme.panel }));
  var series = [
    { a: hist.x, c: 0xff6b6b }, { a: hist.y, c: 0x4a9dff }, { a: hist.z, c: 0x44dd88 }
  ];
  for (var s = 0; s < series.length; s++) {
    var arr = series[s].a;
    if (arr.length < 2) continue;
    var pts = [];
    for (var i = 0; i < arr.length; i++) {
      var v = arr[i] / span;
      if (v > 1) v = 1;
      if (v < -1) v = -1;
      pts.push({ x: Math.round(i * (w - 1) / (HIST_N - 1)),
                 y: Math.round(mid - v * (mid - 2)) });
    }
    kids.push(h('path', { pts: pts, color: series[s].c, w: 1 }));
  }
  return h('box', { w: w, h: hgt }, kids);
}

/* One sensor, one panel. A missing magnetometer is a normal answer, not
   an error, so it is stated rather than hidden. */
function Axes(p) {
  var v = p.v;
  /* Three signed numbers share one row. At size 2 a value like "x-0.02"
     is 72px, so three overrun anything narrower than a 3.5" panel and
     ellipse away to nothing useful. The axis letter joins its number
     (lowercase, no space) and the size steps down where the row is
     tight -- a readable number beats a big one. */
  var sz = gfx.width() >= 320 ? 2 : 1;
  return (
    <box bg={UI.theme.panel} radius={8} pad={em(0.9)} gap={em(0.35)}>
      <row>
        <text text={p.label} size={1} color={UI.theme.muted} />
        <box flex={1} />
        <text text={p.unit} size={1} color={UI.theme.muted} />
      </row>
      {v
        ? <row gap={em(0.5)}>
            <text text={'x' + fmt(v.x, p.d)} size={sz} color={UI.theme.text} />
            <text text={'y' + fmt(v.y, p.d)} size={sz} color={UI.theme.text} />
            <text text={'z' + fmt(v.z, p.d)} size={sz} color={UI.theme.text} />
          </row>
        : <text text={p.absent || 'not present'} size={1} color={UI.theme.warn} />}
    </box>
  );
}

function App() {
  /* Round glass gets a uniform inset that keeps every panel inside the
     circle. The SHORT labels are a question of width, not shape: the
     1.47" is a perfectly square 172px panel and truncates
     "acceleration" just as readily as the circle does. */
  var round = UI.isRound();
  var narrow = round || gfx.width() < 200;
  var view = UI.state.view || 'LEVEL';
  var a = UI.state.accel || null;
  var g = UI.state.gyro || null;
  var m = UI.state.mag || null;
  var t = UI.state.temp;
  var amag = a ? Math.sqrt(a.x * a.x + a.y * a.y + a.z * a.z) : null;
  pushSample(a);

  var chips = [];
  for (var i = 0; i < VIEWS.length; i++) {
    chips.push(h(Button, {
      label: VIEWS[i], size: 1, pad: em(0.4),
      bg: view === VIEWS[i] ? UI.theme.accent : UI.theme.panel,
      onTap: (function (v) { return function () { UI.set({ view: v }); }; })(VIEWS[i])
    }));
  }

  var kids = [
    h('text', { text: 'MOTION', size: 2, align: 'center', color: UI.theme.accent }),
    h('text', { size: 1, align: 'center', color: UI.theme.muted,
      text: HAVE_IMU ? (INFO.imu || 'sensor') + ' + ' + (INFO.mag || 'no mag')
                     : (narrow ? 'simulated - no hardware'
                               : 'simulated - no motion hardware here') }),
    h('row', { gap: 4 }, chips)
  ];

  if (view === 'LEVEL') {
    /* Page coordinates, because that is the space abs actually uses. The
       dial is centred on the display and sits under the chrome; a flow
       spacer of the same height keeps the caption below it. */
    var top = narrow ? 84 : 92;
    var dial = Math.min(gfx.width() - (narrow ? 40 : 56),
                        gfx.height() - top - (narrow ? 26 : 34));
    if (dial < 50) dial = 50;
    var R = dial >> 1;
    var cx = gfx.width() >> 1, cy = top + R;
    kids.push(h('box', {
      h: dial, onTap: function () {
        configStorage.set('lvl.map', '' + ((mapIdx() + 1) % MAPS.length));
        UI._dirty = true;
      }
    }, levelNodes(a, cx, cy, R)));
    kids.push(h('text', { size: 1, align: 'center', color: UI.theme.muted,
      text: (amag === null ? 'waiting for a reading'
                           : tiltDeg(a) + ' deg   ' + amag.toFixed(2) + ' g') +
            '   tap:' + MAPS[mapIdx()].n }));
  } else if (view === 'TRACE') {
    var tw = gfx.width() - (narrow ? 30 : 46);
    kids.push(h('box', { bg: UI.theme.panel, radius: 8, pad: 4, gap: 2 }, [
      h('text', { text: narrow ? 'x red  y blue  z green'
                                : 'accel   x red   y blue   z green',
                  size: 1, color: UI.theme.muted }),
      h(Trace, { w: tw, h: Math.max(40, Math.floor(gfx.height() / 4)), span: 2 })
    ]));
    kids.push(h('text', { size: 1, align: 'center', color: UI.theme.muted,
      text: hist.x.length < 2 ? 'move the board to draw'
                              : hist.x.length + ' samples, +-2 g' }));
  } else {
    kids.push(h(Axes, { label: narrow ? 'accel' : 'acceleration', unit: 'g', v: a, d: 2 }));
    kids.push(h(Axes, { label: narrow ? 'gyro' : 'rotation', unit: 'deg/s', v: g, d: 1,
                        absent: 'no gyroscope' }));
    kids.push(h(Axes, { label: narrow ? 'mag' : 'magnetic field', unit: 'uT', v: m, d: 1,
                        absent: narrow ? 'none wired' : 'no magnetometer wired' }));
    kids.push(h('box', { bg: UI.theme.panel, radius: 8, pad: em(0.9), gap: em(0.35) }, [
      h('row', {}, [
        h('text', { text: 'derived', size: 1, color: UI.theme.muted }),
        h('box', { flex: 1 }),
        h('text', { text: t === undefined ? '' : fmt(t, 1) + ' C',
                    size: 1, color: UI.theme.muted })
      ]),
      h('text', { size: narrow ? 1 : 2,
                  color: amag === null ? UI.theme.muted : UI.theme.ok,
                  text: amag === null ? 'waiting for a reading'
                                      : 'total ' + amag.toFixed(2) + ' g' })
    ]));
  }

  return h('box', { h: gfx.height(), scroll: 'sensors',
                    pad: round ? em(2.4) : em(1), gap: em(0.6) }, kids);
}

UI.mount(App);

UI.onCleanup(function () {
  if (HAVE_IMU) sys.modCtl('imu', 'stop');
});

/* No hardware: drive the same state so the page is developable anywhere.
   Deliberately NOT started when the module is live -- a simulated needle
   next to a real one would be a lie. */
if (!HAVE_IMU) {
  (function tick() {
    var ms = sys.millis();
    UI.set({
      accel: { x: Math.sin(ms / 900) * 0.5, y: Math.cos(ms / 1300) * 0.5, z: -0.86 },
      gyro: { x: Math.sin(ms / 300) * 40, y: Math.cos(ms / 400) * 40, z: 0 },
      temp: 24.5
    });
    UI.setTimer(tick, 200);   /* a real driver re-arms exactly this way */
  })();
}

/*
 * SVG-style filled paths, even-odd rule. The pentagram is one
 * self-intersecting subpath - alternating fill leaves the inner pentagon
 * open, exactly as fill-rule=evenodd does. The donut is two concentric
 * ring subpaths in ONE path - the inner ring flips the parity back to
 * empty, so the hole is a hole. Stroke and fill compose: fill first,
 * outline on top.
 */
function ngon(cx, cy, r, n, rot, step) {
  var pts = [];
  for (var i = 0; i < n; i++) {
    var a = rot + (i * (step || 1) * 2 * Math.PI) / n;
    pts.push({ x: cx + Math.cos(a) * r, y: cy + Math.sin(a) * r });
  }
  return pts;
}

function App() {
  var star = ngon(60, 62, 42, 5, -Math.PI / 2, 2); /* step 2 = pentagram */
  var donut = [ngon(175, 62, 40, 24, 0), ngon(175, 62, 20, 24, 0)];
  var arrow = [
    { x: 30, y: 150 }, { x: 120, y: 150 }, { x: 120, y: 132 },
    { x: 165, y: 165 }, { x: 120, y: 198 }, { x: 120, y: 180 }, { x: 30, y: 180 }
  ];
  var blob = ngon(200, 178, 34, 7, 0.3);

  return (
    <box h={gfx.height()} pad={em(0.75)} gap={em(0.5)}>
      <text text="SHAPES - even-odd fill" size={1} align="center" color={0x8fb8ff} />
      <box flex={1}>
        <path pts={star} fill={0xffcc44} color={0xdd6644} w={2} />
        <path pts={donut} fill={0x44dd88} />
        <path pts={arrow} fill={0x66aaff} color={0xffffff} w={1} />
        <path pts={blob} fill={0x8855cc} color={0xcfa8ff} w={3} />
      </box>
    </box>
  );
}

UI.mount(App);

/*
 * WiFi setup, in JSX — the native settings page's job, done by a script.
 *
 * Everything is ASYNC against the net.* natives the bridge exposes:
 * net.scan() starts a scan and returns immediately, net.results() says
 * "still looking" (-1 as a string parse failure) until it has a list,
 * net.join(ssid, psk) kicks a join and net.status() reports how it went
 * — this view just polls the cheap getters on its tick. Tapping a
 * network opens the password field with the on-screen Keyboard; open
 * networks join at a tap. On hosts without net.* (the sim, the browser)
 * canned networks stand in so the flow is developable anywhere.
 */

/* Bun injects node builtins as globals, so `typeof net` alone lies on
   the desktop -- the bridge's net object is the one with .scan on it. */
var HAVE_NET = typeof net !== 'undefined' && typeof net.scan === 'function';
var FAKE = [
  { ssid: 'workshop', rssi: -48, open: false },
  { ssid: 'HouseNet-5G', rssi: -61, open: false },
  { ssid: 'cafe-guest', rssi: -74, open: true }
];

function refresh() {
  if (!HAVE_NET) { UI.set({ nets: FAKE, scanning: false }); return; }
  var r = net.results();
  if (r === undefined || r === null) return;
  var txt = '' + r;
  if (txt && txt.charAt(0) === '[') {
    var list = JSON.parse(txt);
    if (list.length || !UI.state.scanning) UI.set({ nets: list, scanning: false });
  }
}

function startScan() {
  UI.set({ scanning: true, nets: [] });
  if (HAVE_NET) net.scan();
  else UI.setTimer(function () { refresh(); }, 600);
}

function statusLine() {
  if (!HAVE_NET) return 'demo mode - no radio here';
  var st = {};
  try { st = JSON.parse('' + net.status()); } catch (e) {}
  if (st.connected) return st.ssid + '  ' + st.ip;
  return 'not connected';
}

function join(ssid, psk) {
  if (HAVE_NET) net.join(ssid, psk);
  UI.set({ joining: ssid, picking: null });
}

function App() {
  var nets = UI.state.nets || [];
  var picking = UI.state.picking || null;
  var focused = UI.focused();

  var kids = [
    <text text="WIFI" size={2} align="center" color={UI.theme.accent} />,
    <text text={statusLine()} size={1} align="center" color={UI.theme.ok} />,
    <Button label={UI.state.scanning ? 'SCANNING...' : 'SCAN'} size={2}
            onTap={startScan} />
  ];

  if (picking !== null) {
    kids.push(
      <box bg={UI.theme.panel} radius={6} pad={em(0.75)} gap={em(0.5)}>
        <text text={'PASSWORD FOR ' + picking} size={1} color={UI.theme.muted} />
        <input id="psk" size={2} password={true} placeholder="password"
               onSubmit={function (v) { join(picking, v); }} />
        <row gap={em(0.5)}>
          <Button label="JOIN" size={1} bg={UI.theme.accent}
                  onTap={function () {
                    UI.key('press', 'Enter');
                  }} />
          <Button label="CANCEL" size={1}
                  onTap={function () { UI.blur(); UI.set({ picking: null }); }} />
        </row>
      </box>
    );
  }

  var list = [];
  for (var i = 0; i < nets.length; i++) {
    list.push(h(Button, {
      label: nets[i].ssid + (nets[i].open ? '' : ' *') + '  ' + nets[i].rssi,
      size: 1, pad: em(0.6),
      onTap: (function (n) {
        return function () {
          if (n.open) join(n.ssid, '');
          else { UI.set({ picking: n.ssid }); UI.focus('psk'); }
        };
      })(nets[i])
    }));
  }
  kids.push(h('box', { flex: 1, scroll: 'nets', gap: em(0.4) }, list));

  if (UI.state.joining) {
    kids.push(<text text={'joining ' + UI.state.joining + '...'} size={1}
                    align="center" color={UI.theme.warn} />);
  }
  /* no layout named: this app wants "whatever types best here", which is
     QWERTY on a phone-ish panel and T9 on a watch */
  if (focused) kids.push(h(Keyboard, { position: 'bottom',
                                       height: Math.floor(gfx.height() / 2.8) }));

  return h('box', { h: gfx.height(), scroll: 'wifi', pad: em(0.75), gap: em(0.6) }, kids);
}

/* poll the cheap getters while scanning or joining; renders come free */
UI.onTick = function () {
  if (UI.state.scanning) refresh();
  if (UI.state.joining) {
    UI.set({ joinTick: (UI.state.joinTick || 0) + 1 });
    if (UI.state.joinTick > 40) UI.set({ joining: null, joinTick: 0 });
  }
};

UI.mount(App);
startScan();
